import{_ as a,I as e,g as n,j as r}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","frontmatter":{"title":"Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","tags":["Экономика","Инструменты","Мастерская"]},"headers":[],"relativePath":"ru/articles/pricing-and-margins.md","filePath":"ru/articles/pricing-and-margins.md"}'),s={name:"ru/articles/pricing-and-margins.md"};function l(i,t,o,c,d,p){return e(),n("div",null,[...t[0]||(t[0]=[r(`<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и гайды</a></div><h1 id="ценообразование-наценка-и-маржа-как-рассчитать-цену-изделия-от-себестоимости" tabindex="-1">Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости <a class="header-anchor" href="#ценообразование-наценка-и-маржа-как-рассчитать-цену-изделия-от-себестоимости" aria-label="Permalink to &quot;Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости&quot;">​</a></h1><p>Один из самых коварных финансовых капканов для частного мастера или небольшой ремесленной мастерской — путаница между <strong>торговой наценкой</strong> и <strong>валовой маржой</strong>.</p><p>Нередка ситуация: мастер считает затраты на материалы и фурнитуру для кожаного портмоне — вышло 2 000 рублей. В голове возникает расчёт: <em>«Хочу заработать 40% прибыли. Сделаю наценку 40%: $2000 \\times 1.4 = 2800$ рублей»</em>. Через месяц мастерская делает скидку постоянному клиенту в 30%, будучи уверенной, что 10% «маржи» всё ещё остаётся в кармане. В реальности заказ закрывается с чистым убытком.</p><p>В этой статье разберём математику ценообразования в производственной мастерской: формулы расчёта цены, фундаментальное отличие наценки от маржи, расчёт точки безубыточности и методику защиты своей прибыли.</p><hr><h2 id="🧭-наценка-vs-маржа-в-чем-принципиальная-разница" tabindex="-1">🧭 Наценка vs Маржа: в чём принципиальная разница? <a class="header-anchor" href="#🧭-наценка-vs-маржа-в-чем-принципиальная-разница" aria-label="Permalink to &quot;🧭 Наценка vs Маржа: в чём принципиальная разница?&quot;">​</a></h2><p>Многие начинающие предприниматели используют слова «наценка» и «маржа» как синонимы. Это грубая ошибка, приводящая к кассовым разрывам.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   АНАТОМИЯ РОЗНИЧНОЙ ЦЕНЫ                │</span></span>
<span class="line"><span>├───────────────────────────────┬──────────────────────────┤</span></span>
<span class="line"><span>│ Себестоимость изделия (100%)  │ Торговая наценка (66.7%) │</span></span>
<span class="line"><span>├───────────────────────────────┴──────────────────────────┤</span></span>
<span class="line"><span>│           ИТОГОВАЯ ЦЕНА ПРОДАЖИ (100% ВЫРУЧКИ)           │</span></span>
<span class="line"><span>│                                                          │</span></span>
<span class="line"><span>│ ◀── Доля себестоимости: 60% ──▶ ◀── Валовая маржа: 40% ──▶</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_1-торговая-наценка-markup" tabindex="-1">1. Торговая наценка (Markup) <a class="header-anchor" href="#_1-торговая-наценка-markup" aria-label="Permalink to &quot;1. Торговая наценка (Markup)&quot;">​</a></h3><p>Наценка показывает, <strong>на сколько процентов розничная цена выше себестоимости</strong>. Она отталкивается от затрат.</p><p>$$\\text{Наценка (%)} = \\frac{\\text{Цена продажи} - \\text{Себестоимость}}{\\text{Себестоимость}} \\times 100%$$</p><ul><li><strong>Пределы:</strong> наценка может составлять 50%, 100%, 300% и более. Если себестоимость чехла для очков 500 рублей, а продаёте вы его за 1 500 рублей, ваша наценка составляет 200%.</li></ul><h3 id="_2-маржинальность-или-маржа-margin" tabindex="-1">2. Маржинальность или маржа (Margin) <a class="header-anchor" href="#_2-маржинальность-или-маржа-margin" aria-label="Permalink to &quot;2. Маржинальность или маржа (Margin)&quot;">​</a></h3><p>Маржа показывает, <strong>какую долю в итоговой выручке составляют «чистые» заработанные деньги</strong>. Она отталкивается от продажной цены.</p><p>$$\\text{Маржа (%)} = \\frac{\\text{Цена продажи} - \\text{Себестоимость}}{\\text{Цена продажи}} \\times 100%$$</p><ul><li><strong>Пределы:</strong> маржа <strong>никогда не может превышать 100%</strong>. Если изделие продано за 2 000 рублей, то даже при нулевой себестоимости маржа будет ровно 100%.</li></ul><h3 id="сравнительная-таблица-соответствия-наценки-и-маржи" tabindex="-1">Сравнительная таблица соответствия наценки и маржи <a class="header-anchor" href="#сравнительная-таблица-соответствия-наценки-и-маржи" aria-label="Permalink to &quot;Сравнительная таблица соответствия наценки и маржи&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Себестоимость (₽)</th><th style="text-align:center;">Желаемая маржа (%)</th><th style="text-align:center;">Необходимая наценка (%)</th><th style="text-align:center;">Розничная цена (₽)</th><th style="text-align:center;">Фактическая прибыль (₽)</th></tr></thead><tbody><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>20%</strong></td><td style="text-align:center;"><strong>25%</strong></td><td style="text-align:center;">1 250</td><td style="text-align:center;">250</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>30%</strong></td><td style="text-align:center;"><strong>43%</strong></td><td style="text-align:center;">1 428</td><td style="text-align:center;">428</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>40%</strong></td><td style="text-align:center;"><strong>67%</strong></td><td style="text-align:center;">1 667</td><td style="text-align:center;">667</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>50%</strong></td><td style="text-align:center;"><strong>100%</strong></td><td style="text-align:center;">2 000</td><td style="text-align:center;">1 000</td></tr><tr><td style="text-align:center;">1 000</td><td style="text-align:center;"><strong>60%</strong></td><td style="text-align:center;"><strong>150%</strong></td><td style="text-align:center;">2 500</td><td style="text-align:center;">1 500</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Если вы хотите получить рентабельность продаж (маржу) 40%, вам необходимо делать наценку на себестоимость <strong>не 40%, а 67%</strong>. Если вы просто нацените 40%, ваша фактическая маржа составит всего 28.5%.</p></div><hr><h2 id="🧮-как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" tabindex="-1">🧮 Как рассчитать розничную цену, зная себестоимость и целевую маржу <a class="header-anchor" href="#🧮-как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" aria-label="Permalink to &quot;🧮 Как рассчитать розничную цену, зная себестоимость и целевую маржу&quot;">​</a></h2><p>Когда мастер определяет продажную стоимость изделия, правильный ход мысли — идти не от наценки, а от <strong>целевой рентабельности</strong>.</p><h3 id="формула-расчета-цены-от-маржи" tabindex="-1">Формула расчёта цены от маржи: <a class="header-anchor" href="#формула-расчета-цены-от-маржи" aria-label="Permalink to &quot;Формула расчёта цены от маржи:&quot;">​</a></h3><p>$$\\text{Цена продажи} = \\frac{\\text{Полная себестоимость}}{1 - \\frac{\\text{Целевая маржа (%)}}{100}}$$</p><h4 id="пример-из-цеха" tabindex="-1">Пример из цеха: <a class="header-anchor" href="#пример-из-цеха" aria-label="Permalink to &quot;Пример из цеха:&quot;">​</a></h4><ul><li>Полная себестоимость ремня (кожа чепрак с учётом обрезков + пряжка + 2 часа работы мастера + износ инструмента) = <strong>2 400 ₽</strong>.</li><li>Мастерская стремится к маржинальности <strong>35%</strong> (чтобы покрывать аренду, налоги и откладывать на развитие).</li></ul><p>$$\\text{Цена продажи} = \\frac{2400}{1 - 0.35} = \\frac{2400}{0.65} \\approx 3690\\text{ ₽}$$</p><p>Если бы мастер по ошибке просто прибавил 35% к себестоимости, цена составила бы $2400 \\times 1.35 = 3240$ ₽. Потеря на каждом ремне составила бы <strong>450 рублей</strong> чистой прибыли.</p><hr><h2 id="📐-три-метода-ценообразования-в-ремесленном-производстве" tabindex="-1">📐 Три метода ценообразования в ремесленном производстве <a class="header-anchor" href="#📐-три-метода-ценообразования-в-ремесленном-производстве" aria-label="Permalink to &quot;📐 Три метода ценообразования в ремесленном производстве&quot;">​</a></h2><p>На практике мастерские используют три базовых подхода к назначению цен:</p><h3 id="_1-затратныи-метод-«себестоимость-плюс»" tabindex="-1">1. Затратный метод («Себестоимость плюс») <a class="header-anchor" href="#_1-затратныи-метод-«себестоимость-плюс»" aria-label="Permalink to &quot;1. Затратный метод («Себестоимость плюс»)&quot;">​</a></h3><p>Классический инженерный подход. Вы суммируете все прямые затраты (материалы, полезный раскрой, фурнитуру), оплату труда мастера за затраченные часы, долю постоянных накладных расходов (аренда помещения, амортизация оборудования, расходники) и закладываете фиксированную норму прибыли.</p><ul><li><strong>Плюсы:</strong> гарантирует окупаемость каждого изделия и защиту от работы в минус.</li><li><strong>Минусы:</strong> не учитывает рыночный спрос и ценность авторского дизайна.</li></ul><h3 id="_2-рыночныи-метод-анализ-конкурентов" tabindex="-1">2. Рыночный метод (Анализ конкурентов) <a class="header-anchor" href="#_2-рыночныи-метод-анализ-конкурентов" aria-label="Permalink to &quot;2. Рыночный метод (Анализ конкурентов)&quot;">​</a></h3><p>Мастер изучает витрины ярмарок и социальных сетей других ремесленников схожего уровня и выставляет среднерыночную стоимость.</p><ul><li><strong>Опасность метода:</strong> конкурент может работать дома на старых складских запасах сырья без учёта стоимости своего труда. Слепое копирование чужих цен часто приводит к скрытым убыткам.</li></ul><h3 id="_3-ценностныи-метод-премиальное-ценообразование" tabindex="-1">3. Ценностный метод (Премиальное ценообразование) <a class="header-anchor" href="#_3-ценностныи-метод-премиальное-ценообразование" aria-label="Permalink to &quot;3. Ценностный метод (Премиальное ценообразование)&quot;">​</a></h3><p>Цена определяется не затратами материалов, а эмоциональной ценностью, статусностью, уникальностью ручной работы и качеством сервиса (подарочная упаковка, пожизненная гарантия на швы, индивидуальное тиснение).</p><ul><li><strong>Плюсы:</strong> максимальная маржа (от 60% до 80%).</li></ul><hr><h2 id="⚖️-точка-безубыточности-мастерскои" tabindex="-1">⚖️ Точка безубыточности мастерской <a class="header-anchor" href="#⚖️-точка-безубыточности-мастерскои" aria-label="Permalink to &quot;⚖️ Точка безубыточности мастерской&quot;">​</a></h2><p><strong>Точка безубыточности (Break-Even Point)</strong> — это объём продаж, при котором выручка мастерской в точности покрывает все постоянные и переменные расходы. Прибыль в этой точке равна нулю: мастерская не терпит убытков, но ещё ничего не заработала сверх расходов.</p><p>$$\\text{Точка безубыточности (в штуках)} = \\frac{\\text{Постоянные расходы в месяц}}{\\text{Цена изделия} - \\text{Переменная себестоимость изделия}}$$</p><h4 id="пример" tabindex="-1">Пример: <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример:&quot;">​</a></h4><ul><li>Аренда мастерской, отопление и интернет: <strong>30 000 ₽/мес</strong>.</li><li>Розничная цена сумки: <strong>9 000 ₽</strong>.</li><li>Переменная себестоимость одной сумки (кожа, нитки, молния, фурнитура): <strong>4 000 ₽</strong>.</li><li>Маржинальный доход с одного изделия: $9000 - 4000 = 5000$ ₽.</li></ul><p>$$\\text{Точка безубыточности} = \\frac{30000}{5000} = 6\\text{ сумок в месяц}$$</p><p>Первые 6 сумок каждого месяца работают исключительно на покрытие аренды и коммунальных счетов. И только начиная с 7-й сумки мастерская начинает формировать прибыль владельца.</p><hr><h2 id="🛠️-с-чего-начать-точныи-расчет-базы" tabindex="-1">🛠️ С чего начать: точный расчёт базы <a class="header-anchor" href="#🛠️-с-чего-начать-точныи-расчет-базы" aria-label="Permalink to &quot;🛠️ С чего начать: точный расчёт базы&quot;">​</a></h2><p>Невозможно выстроить надёжное ценообразование, если в фундаменте лежит неверная себестоимость: не учтены обрезки сырья, не оцифрована ставка собственного рабочего часа или забыта амортизация оборудования.</p><p>Воспользуйтесь нашим интерактивным инструментом для расчета реальной производственной базы:</p><div class="cta-calc-box"><div class="cta-calc-content"><h3>Рассчитайте точную себестоимость изделия онлайн</h3><p>Наш бесплатный калькулятор оцифрует обрезки кожи по коэффициенту раскроя, посчитает стоимость вашего часа работы и выдаст диагноз рентабельности заказа.</p><a href="/ru/articles/leather-cost-calculator" class="vp-button brand" data-omni-event="sat_pricing_cta_calc"> Перейти в калькулятор себестоимости → </a></div></div><hr><h2 id="📚-связанные-статьи-производственного-кластера" tabindex="-1">📚 Связанные статьи производственного кластера <a class="header-anchor" href="#📚-связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;📚 Связанные статьи производственного кластера&quot;">​</a></h2><ul><li>🧮 <strong><a href="/ru/articles/leather-cost-calculator">Калькулятор себестоимости онлайн: расчёт изделия из кожи и шаблон Excel</a></strong> — интерактивный инструмент и разбор финансовых ловушек ручного труда.</li><li>💻 <strong><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a></strong> — обзор учётных систем для растущего производства.</li></ul>`,57)])])}const u=a(s,[["render",l]]);export{h as __pageData,u as default};
